	@Test
	void legalPrefixGateRunsOncePerKeyAndKeepsEveryFanoutRow() throws Exception {
		SyntheticValueSource source = SyntheticValueSource.forEvaluation(mock(NativeLmdbQuerySource.class));
		NativeSlotLayout layout = new NativeSlotLayout(Map.of("outer", 0, "value", 1), null);
		layout.freeze(List.of("outer", "value"));
		RowState row = new RowState(source, layout, EmptyBindingSet.getInstance());
		assertThat(NativeRowSeeder.seed(row.slots, layout, row.base, source)).isTrue();
		NativeBooleanFilter exists = witness();
		AtomicInteger gates = new AtomicInteger();
		NativeBooleanFilter counted = new NativeBooleanFilter() {
			@Override
			public boolean accept(RowState input) {
				gates.incrementAndGet();
				return exists.accept(input);
			}

			@Override
			public NativePredicateCapabilities capabilities() {
				return exists.capabilities();
			}
		};
		SlotPlan plan = SlotPlan.filter(new JoinPlan(values(0, 10L, 20L),
				new UnionPlan(values(1, 11L, 12L), values(1, 13L))), counted, 1L);
		try (RowCursor cursor = plan.open(row)) {
			int count = 0;
			while (cursor.next()) {
				count++;
				assertThat(row.slots[0]).isEqualTo(10L);
			}
			assertThat(count).isEqualTo(3);
			assertThat(gates).hasValue(2);
		} finally {
			row.memoryScope.close();
			source.executionContext().close();
		}
	}

	@Test
	void compoundWitnessMovesBeforeIndependentUnionFanout() {
		SlotPlan root = values(0, 10L);
		SlotPlan fanout = new UnionPlan(values(1, 11L, 12L), values(1, 13L));
		NativeBooleanFilter witness = witness();
		SlotPlan planned = SlotPlan.filter(new JoinPlan(root, fanout), witness, 1L);
		assertThat(planned).isInstanceOf(JoinPlan.class);
		JoinPlan join = (JoinPlan) planned;
		assertThat(join.right).isSameAs(fanout);
		assertThat(join.left).isInstanceOf(FilterPlan.class);
		assertThat(((FilterPlan) join.left).arg).isSameAs(root);
		assertThat(((FilterPlan) join.left).filter).isSameAs(witness);
	}

	@Test
	void compoundWitnessDescendsThroughNestedPureJoins() {
		SlotPlan root = values(0, 10L);
		SlotPlan first = new UnionPlan(values(1, 11L), values(1, 12L));
		SlotPlan second = new UnionPlan(values(2, 21L), values(2, 22L));
		SlotPlan planned = SlotPlan.filter(new JoinPlan(new JoinPlan(root, first), second), witness(), 1L);
		assertThat(planned).isInstanceOf(JoinPlan.class);
		assertThat(((JoinPlan) planned).left).isInstanceOf(JoinPlan.class);
		JoinPlan inner = (JoinPlan) ((JoinPlan) planned).left;
		assertThat(inner.left).isInstanceOf(FilterPlan.class);
		assertThat(((FilterPlan) inner.left).arg).isSameAs(root);
		assertThat(inner.right).isSameAs(first);
		assertThat(((JoinPlan) planned).right).isSameAs(second);
	}

