	@ParameterizedTest
	@CsvSource({ "false, 1", "false, 3", "true, 1", "true, 3" })
	void laterJoinCannotBindAnUnmaskedWitnessLocal(boolean negated, long mask) throws Exception {
		SyntheticValueSource source = SyntheticValueSource.forEvaluation(mock(NativeLmdbQuerySource.class));
		NativeSlotLayout layout = new NativeSlotLayout(Map.of("outer", 0, "local", 1), null);
		layout.freeze(List.of("outer", "local"));
		RowState row = new RowState(source, layout, EmptyBindingSet.getInstance());
		assertThat(NativeRowSeeder.seed(row.slots, layout, row.base, source)).isTrue();
		NativeBooleanFilter exists = new ExistsFilter(new JoinPlan(values(0, 10L), values(1, 100L)));
		NativeBooleanFilter predicate = negated ? new NegatedNativeBooleanFilter(exists, true) : exists;
		SlotPlan originalGate = SlotPlan.filter(values(0, 10L), predicate, mask);
		SlotPlan joined = SlotPlan.join(originalGate, values(1, 200L));
		try {
			assertThat(joined).as("a later sibling must not change the witness input frame")
					.isNotInstanceOf(MultiJoinPlan.class);
			try (RowCursor cursor = joined.open(row)) {
				assertThat(cursor.next()).isEqualTo(!negated);
				if (!negated) {
					assertThat(row.slots[1]).isEqualTo(200L);
					assertThat(cursor.next()).isFalse();
				}
			}
		} finally {
			row.memoryScope.close();
			source.executionContext().close();
		}
	}

