	@Test
	void leasedCloseOnceWitnessKeepsUnknownReadProof() {
		SlotPlan unknownWitness = new SlotPlan() {
			@Override
			public RowCursor open(RowState row) throws IOException {
				throw new IOException("not opened during planning");
			}

			@Override
			public long producedMask() {
				return 2L;
			}
		};
		NativeFilterLease lease = new NativeFilterLease(true);
		NativeBooleanFilter borrowed = lease.borrow(new CloseOnceNativeBooleanFilter(new ExistsFilter(unknownWitness)));
		try {
			SlotPlan gate = SlotPlan.filter(values(0, 10L), borrowed, 1L);
			assertThat(((FilterPlan) gate).groupedReadMask()).isEqualTo(-1L);
			assertThat(SlotPlan.join(gate, values(1, 200L))).isNotInstanceOf(MultiJoinPlan.class);
		} finally {
			lease.commit();
		}
	}

	@Test
	void semanticCallbackWithUnknownReadsKeepsItsLexicalBoundary() {
		NativeBindingSetValueEvaluator evaluator = bindings -> NativeValueOutcome.ERROR;
		GenericSubplanDescriptor descriptor = GenericSubplanDescriptor.create(new Var("outer"));
		NativeBooleanFilter unknown = new NativeValueOutcomeBooleanFilter(evaluator, -1L);
		NativeScalarPlan scalar = NativeScalarPlan.value(new Var("outer"), name -> 0, false, 0L, false, false);
		NativeBooleanFilter[] callbacks = {
				unknown,
				new NativeValueOutcomeBooleanFilter(descriptor, context -> evaluator, () -> evaluator, -1L),
				new FragmentTruthFilter(null, new int[0], new long[0], unknown),
				new NonOwningAdaptiveFilter(unknown),
				new PlannedNativeBooleanFilter(unknown, scalar),
				new NegatedNativeBooleanFilter(unknown, true),
				new BooleanCombinationFilter(unknown, row -> true, true) };
		for (NativeBooleanFilter callback : callbacks) {
			SlotPlan gate = SlotPlan.filter(values(0, 10L), callback, 1L);
			assertThat(((FilterPlan) gate).groupedReadMask()).isEqualTo(-1L);
			assertThat(SlotPlan.join(gate, values(1, 200L))).isNotInstanceOf(MultiJoinPlan.class);
		}
	}

	private static NativeBooleanFilter witness() {
		return new ExistsFilter(new JoinPlan(values(0, 10L), SingletonPlan.INSTANCE));
	}

	private static StatementPattern pattern(String subject, String predicate, String object) {
		return new StatementPattern(new Var(subject),
				new Var("constant-" + predicate, SimpleValueFactory.getInstance().createIRI("urn:" + predicate)),
				new Var(object));
	}

	private static ValuesPlan values(int slot, long... values) {
		ValuesRow[] rows = new ValuesRow[values.length];
		for (int i = 0; i < values.length; i++) {
			rows[i] = new ValuesRow(new int[] { slot }, new long[] { values[i] });
		}
		return new ValuesPlan(rows);
	}

	private static NativeBooleanFilter scalar(long reads) {
		return new NativeBooleanFilter() {
			@Override
			public boolean accept(RowState row) {
				return true;
			}

			@Override
			public NativePredicateCapabilities capabilities() {
				return new NativePredicateCapabilities(reads, EffectClass.PURE, false, true, true, false, false);
			}
		};
	}

	private static NativeBooleanFilter slotEquals(int slot, long expected) {
		return new NativeBooleanFilter() {
			@Override
			public boolean accept(RowState row) {
				return row.slots[slot] == expected;
			}

			@Override
			public NativePredicateCapabilities capabilities() {
				return scalar(1L << slot).capabilities();
			}
		};
	}

	private static int drainInOrder(SlotPlan plan) throws IOException {
		SyntheticValueSource source = SyntheticValueSource.forEvaluation(mock(NativeLmdbQuerySource.class));
		NativeSlotLayout layout = new NativeSlotLayout(Map.of("source", 0, "value", 1, "alias", 2, "other", 3),
				null);
		layout.freeze(List.of("source", "value", "alias", "other"));
		RowState row = new RowState(source, layout, EmptyBindingSet.getInstance());
		row.encounterOrderRequired = true;
		assertThat(NativeRowSeeder.seed(row.slots, layout, row.base, source)).isTrue();
		try (RowCursor cursor = plan.open(row)) {
			int count = 0;
			while (cursor.next()) {
				count++;
			}
			return count;
		} finally {
			row.memoryScope.close();
			source.executionContext().close();
		}
	}
